@php
    $formatDate = static function ($value, bool $withTime = true): string {
        if (! $value) return '-';
        try { return \Carbon\Carbon::parse($value)->timezone('Asia/Jakarta')->format($withTime ? 'd-m-Y H:i:s' : 'd-m-Y'); }
        catch (\Throwable) { return (string) $value; }
    };
    $number = static fn ($value, int $decimals = 2): string => number_format((float) ($value ?? 0), $decimals, ',', '.');
    $operatorLabel = $operator !== '' ? $operator : 'Semua operator sesuai filter';
    $processLabel = $process !== '' ? $process : 'Semua proses sesuai filter';
@endphp
